{"name":"ensureTaskForRepoActivityWithProxy","qualified_name":"Users-appointy-Documents-New-project-6.internal.taskpilot.cli.ensureTaskForRepoActivityWithProxy","label":"Function","file_path":"/Users/appointy/Documents/New project 6/internal/taskpilot/cli.go","start_line":694,"end_line":725,"source":"func ensureTaskForRepoActivityWithProxy(activity repoActivity, allowProxy bool) (Task, error) {
	if match, err := resolveRepoTaskWithProxy(activity, allowProxy); err == nil && match.Task.ID != "" && match.Score >= 80 {
		mergedScope := appendUniqueStrings(filterProductRepoFiles(match.Task.Scope), activity.ChangedFiles...)
