{"name":"listTaskDependencyRows","qualified_name":"Users-appointy-Documents-New-project-6.internal.taskpilot.store.listTaskDependencyRows","label":"Method","file_path":"/Users/appointy/Documents/New project 6/internal/taskpilot/store.go","start_line":1330,"end_line":1362,"source":"func (s *Store) listTaskDependencyRows(ctx context.Context, where, id string) ([]TaskDependency, error) {
	rows, err := s.query(ctx, `SELECT id,task_id,depends_on_id,created_by,created_at FROM task_dependencies `+where+` ORDER BY created_at DESC`, id)
	if err != nil {
		return nil, err
	}
	out := []TaskDependency{}
	for rows.Next() {
		var dep TaskDependency
		var created string
		if err := rows.Scan(&dep.ID, &dep.TaskID, &dep.DependsOnID, &dep.CreatedBy, &created); err != nil {
			_ = rows.Close()
			return nil, err
		}
		dep.CreatedAt = parseTS(created)
		out = append(out, dep)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return nil, err
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	for i := range out {
		if t, err := s.GetTask(ctx, out[i].TaskID); err == nil {
			out[i].Task = &t
		}
		if t, err := s.GetTask(ctx, out[i].DependsOnID); err == nil {
			out[i].DependsOnTask = &t
		}
	}
	return out, nil
}
