{"name":"taskSearchText","qualified_name":"Users-appointy-Documents-New-project-6.internal.taskpilot.store.taskSearchText","label":"Method","file_path":"/Users/appointy/Documents/New project 6/internal/taskpilot/store.go","start_line":2740,"end_line":2763,"source":"func (s *Store) taskSearchText(ctx context.Context, taskID string) string {
	parts := []string{}
	rows, err := s.query(ctx, `SELECT content FROM context_entries WHERE task_id=? ORDER BY created_at DESC LIMIT 20`, taskID)
	if err == nil {
		for rows.Next() {
			var content string
			if rows.Scan(&content) == nil {
				parts = append(parts, content)
			}
		}
		_ = rows.Close()
	}
	rows, err = s.query(ctx, `SELECT decision,reason,impact FROM decision_records WHERE task_id=? ORDER BY created_at DESC LIMIT 20`, taskID)
	if err == nil {
		for rows.Next() {
			var decision, reason, impact string
			if rows.Scan(&decision, &reason, &impact) == nil {
				parts = append(parts, decision, reason, impact)
			}
		}
		_ = rows.Close()
	}
	return strings.Join(parts, " ")
}
